from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        buckets = [[] for _ in range(n + 1)]

        for idx, (x, y) in enumerate(conflictingPairs):
            if x > y:
                x, y = y, x
            buckets[x].append((y, idx))

        gains = [0] * m

        sentinel = n + 1
        min_b = sentinel
        min_count = 0
        min_id = -1
        second_b = sentinel

        baseline = 0

        for left in range(n, 0, -1):
            for b, idx in buckets[left]:
                if b < min_b:
                    second_b = min_b
                    min_b = b
                    min_count = 1
                    min_id = idx
                elif b == min_b:
                    min_count += 1
                    min_id = -1
                elif b < second_b:
                    second_b = b

            if min_b == sentinel:
                baseline += sentinel - left
            else:
                baseline += min_b - left
                if min_count == 1:
                    gains[min_id] += second_b - min_b

        return baseline + max(gains)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        pat = [ord(c) - 97 for c in str2]
        states = m + 1
        trans = [[0] * 26 for _ in range(states)]

        for q in range(states):
            if q < m:
                target = pat[q]
                if q == 0:
                    for ci in range(26):
                        trans[q][ci] = 1 if ci == target else 0
                else:
                    fallback = trans[pi[q - 1]]
                    row = trans[q]
                    for ci in range(26):
                        if ci == target:
                            row[ci] = q + 1
                        else:
                            row[ci] = fallback[ci]
            else:
                fallback = trans[pi[m - 1]]
                row = trans[q]
                for ci in range(26):
                    row[ci] = fallback[ci]

        single = [0] * states
        for q in range(states):
            bit = 1 << q
            row = trans[q]
            for ci in range(26):
                single[row[ci]] |= bit

        all_mask = (1 << states) - 1
        bit_m = 1 << m
        not_m_mask = all_mask ^ bit_m
        canT_mask = single[m]

        B = 8
        SIZE = 1 << B
        CHUNK_MASK = SIZE - 1
        chunks = (states + B - 1) // B
        table = []
        for k in range(chunks):
            shift = k * B
            tbl = [0] * SIZE
            for v in range(1, SIZE):
                lb = v & -v
                idx = lb.bit_length() - 1
                t = shift + idx
                prev = v ^ lb
                if t < states:
                    tbl[v] = tbl[prev] | single[t]
                else:
                    tbl[v] = tbl[prev]
            table.append(tbl)

        def preimage(mask: int, table=table, chunk_mask=CHUNK_MASK, B=B) -> int:
            res = 0
            for tbl in table:
                if not mask:
                    break
                v = mask & chunk_mask
                if v:
                    res |= tbl[v]
                mask >>= B
            return res

        feas = [0] * (L + 1)
        feas[L] = all_mask
        m_minus_1 = m - 1

        for p in range(L - 1, -1, -1):
            nxt = feas[p + 1]
            if p < m_minus_1:
                feas[p] = preimage(nxt)
            else:
                if str1[p - m_minus_1] == 'T':
                    feas[p] = canT_mask if (nxt & bit_m) else 0
                else:
                    feas[p] = preimage(nxt & not_m_mask)

        if not (feas[0] & 1):
            return ""

        bits = [1 << i for i in range(states)]
        ans = []
        state = 0

        for p in range(L):
            nxt = feas[p + 1]
            if p < m_minus_1:
                allowed = nxt
            elif str1[p - m_minus_1] == 'T':
                allowed = bit_m if (nxt & bit_m) else 0
            else:
                allowed = nxt & not_m_mask

            row = trans[state]
            chosen = -1
            for ci in range(26):
                ns = row[ci]
                if allowed & bits[ns]:
                    chosen = ci
                    break

            if chosen == -1:
                return ""

            ans.append(chr(97 + chosen))
            state = row[chosen]

        return "".join(ans)

import sys
from collections import deque
import random


def formula_solve(N, A, B):
    # A and B are bytes.  Positions are 0-indexed.
    a = [i for i, c in enumerate(A) if c == 49]  # ord('1') == 49
    b = [i for i, c in enumerate(B) if c == 49]

    m = len(a)
    k = len(b)

    if m < k:
        return -1

    # D is the total required reduction of the span.
    D = (a[-1] - a[0]) - (b[-1] - b[0])
    if D < 0:
        return -1

    # Universal lower bound.
    E = max(abs(b[0] - a[0]), abs(b[-1] - a[-1]), (D + 1) // 2)

    # If there is only one target occupied square, there are no target gaps.
    if k == 1:
        return E

    mk = k - 1
    G = [a[i + 1] - a[i] for i in range(m - 1)]
    H = [b[i + 1] - b[i] for i in range(mk)]

    # 1) Try to match every target gap to a strictly larger initial gap.
    #    Then no exact gap exists, and the lower bound E is attainable.
    j = 0
    for g in G:
        if g > H[j]:
            j += 1
            if j == mk:
                return E

    # 2) Otherwise, all exact gaps must have the same displacement parity.
    #    For each parity p, greedily test whether H can be matched using:
    #      - strict matches g > h, or
    #      - exact matches g == h whose displacement parity is p.
    ans = -1
    for p in (0, 1):
        j = 0
        for i, g in enumerate(G):
            h = H[j]
            if g > h or (g == h and ((b[j] - a[i]) & 1) == p):
                j += 1
                if j == mk:
                    cand = E if (E & 1) == p else E + 1
                    if ans == -1 or cand < ans:
                        ans = cand
                    break

    return ans


# ----------------------------------------------------------------------
# Brute-force BFS oracle for tiny N, used only by the validation harness.
# ----------------------------------------------------------------------
def bfs_solve(N, A, B):
    init = tuple(1 if c == 49 else 0 for c in A)
    goal = tuple(1 if c == 49 else 0 for c in B)

    def occ(state):
        return tuple(1 if v > 0 else 0 for v in state)

    if occ(init) == goal:
        return 0

    q = deque([init])
    dist = {init: 0}

    while q:
        st = q.popleft()
        nd = dist[st] + 1

        for c in range(N):
            new = [0] * N
            for x, cnt in enumerate(st):
                if cnt:
                    if c > x:
                        nx = x + 1
                    elif c < x:
                        nx = x - 1
                    else:
                        nx = x
                    new[nx] += cnt

            ns = tuple(new)
            if ns not in dist:
                if occ(ns) == goal:
                    return nd
                dist[ns] = nd
                q.append(ns)

    return -1


def mask_to_bytes(mask, N):
    return bytes(49 if (mask >> i) & 1 else 48 for i in range(N))


def run_validation():
    mismatches = []

    # Exhaustive for N <= 5.
    for N in range(1, 6):
        strs = [mask_to_bytes(mask, N) for mask in range(1, 1 << N)]
        for A in strs:
            for B in strs:
                f = formula_solve(N, A, B)
                bfs = bfs_solve(N, A, B)
                if f != bfs:
                    mismatches.append((N, A.decode(), B.decode(), f, bfs))

    # Randomized for N <= 6.
    random.seed(12345)
    for _ in range(1000):
        N = random.randint(1, 6)
        A = mask_to_bytes(random.randrange(1, 1 << N), N)
        B = mask_to_bytes(random.randrange(1, 1 << N), N)
        f = formula_solve(N, A, B)
        bfs = bfs_solve(N, A, B)
        if f != bfs:
            mismatches.append((N, A.decode(), B.decode(), f, bfs))

    if mismatches:
        print("counterexamples found")
        for x in mismatches[:50]:
            print(x)
    else:
        print("no counterexamples found")


def solve_input(data):
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        N = int(data[idx])
        A = data[idx + 1]
        B = data[idx + 2]
        idx += 3
        out.append(str(formula_solve(N, A, B)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    data = sys.stdin.buffer.read().split()
    if not data:
        run_validation()
    elif data[0] == b"VALIDATE":
        run_validation()
    else:
        solve_input(data)

from typing import List
import heapq
from bisect import bisect_left


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        if k <= 1 or n <= 1 or k > n:
            return 0

        two_side = 2 * side

        # chain 0: bottom + right, chain 1: left + top.
        # Corners are assigned to exactly one chain.
        arr = []
        for x, y in points:
            if y == 0:
                ch = 0
            elif x == side:
                ch = 0
            elif x == 0:
                ch = 1
            else:
                ch = 1

            u = x + y
            other = two_side - u
            h = u if u < other else other
            arr.append((u, ch, h))

        arr.sort()

        us = [0] * n
        chs = [0] * n
        hs = [0] * n
        for i, (u, ch, h) in enumerate(arr):
            us[i] = u
            chs[i] = ch
            hs[i] = h

        sorted_h = sorted(set(hs))
        m = len(sorted_h)

        # Fenwick tree over reversed h-ranks:
        # h >= threshold becomes a prefix query.
        h_to_rev = {h: m - i for i, h in enumerate(sorted_h)}
        hrev = [h_to_rev[h] for h in hs]

        # Precompute Fenwick traversal paths to reduce bit operations inside
        # the binary-search feasibility checks.
        qpaths = [()] * (m + 1)
        for q in range(1, m + 1):
            x = q
            path = []
            while x:
                path.append(x)
                x &= x - 1
            qpaths[q] = tuple(path)

        upaths = [()] * (m + 1)
        for p in range(1, m + 1):
            x = p
            path = []
            while x <= m:
                path.append(x)
                x += x & -x
            upaths[p] = tuple(path)

        upaths_idx = [upaths[hrev[i]] for i in range(n)]

        INF = 10 ** 30
        SENT = -10 ** 30

        heappush = heapq.heappush
        heappop = heapq.heappop
        bl = bisect_left

        def feasible(d: int) -> bool:
            if d == 0:
                return True

            us_l = us
            ch_l = chs
            hs_l = hs
            sh = sorted_h
            m_l = m
            n_l = n
            k_l = k
            INF_l = INF
            SENT_l = SENT
            push = heappush
            pop = heappop
            bl_l = bl
            qpaths_l = qpaths
            upaths_idx_l = upaths_idx

            # qidx[r] is the Fenwick prefix length representing active states
            # with h_i >= d - h_r.
            qidx = [0] * n_l
            for i in range(n_l):
                pos = bl_l(sh, d - hs_l[i])
                if pos < m_l:
                    qidx[i] = m_l - pos
            qpaths_idx = [qpaths_l[q] for q in qidx]
            qpaths_idx_l = qpaths_idx

            # Length 1: every point is reachable, with no relevant opposite point.
            dp = [SENT_l] * n_l
            start_idx = 0
            first_u = us_l[0]
            limit = first_u + d

            # Build lengths 2..k.
            for layer in range(1, k_l):
                if n_l - start_idx < k_l - layer:
                    return False

                ndp = [INF_l] * n_l

                heap0 = []
                heap1 = []
                tree0 = [INF_l] * (m_l + 1)
                tree1 = [INF_l] * (m_l + 1)
                min0 = INF_l
                min1 = INF_l

                first_idx = n_l

                for idx in range(start_idx, n_l):
                    u = us_l[idx]

                    # If some previous reachable state ends at least d behind,
                    # it can be extended to this and every later point, and the
                    # new state has no relevant opposite point.
                    if u >= limit:
                        if first_idx == n_l:
                            first_idx = idx
                        ndp[idx:] = [SENT_l] * (n_l - idx)
                        break

                    # Activate previous states whose stored opposite point is
                    # already d behind current u.
                    while heap0 and heap0[0][0] <= u:
                        _, i = pop(heap0)
                        ui = us_l[i]
                        if ui < min0:
                            min0 = ui
                        for pos in upaths_idx_l[i]:
                            if ui < tree0[pos]:
                                tree0[pos] = ui
                            else:
                                break

                    while heap1 and heap1[0][0] <= u:
                        _, i = pop(heap1)
                        ui = us_l[i]
                        if ui < min1:
                            min1 = ui
                        for pos in upaths_idx_l[i]:
                            if ui < tree1[pos]:
                                tree1[pos] = ui
                            else:
                                break

                    # Near transition: previous ending point must be on the
                    # opposite chain, its stored opposite point must be far
                    # enough, and cross-chain distance must be at least d.
                    q = qidx_l[idx]
                    if q:
                        if ch_l[idx] == 0:
                            if q == m_l:
                                res = min1
                            else:
                                res = INF_l
                                tree = tree1
                                for pos in qpaths_idx_l[idx]:
                                    tv = tree[pos]
                                    if tv < res:
                                        res = tv
                        else:
                            if q == m_l:
                                res = min0
                            else:
                                res = INF_l
                                tree = tree0
                                for pos in qpaths_idx_l[idx]:
                                    tv = tree[pos]
                                    if tv < res:
                                        res = tv

                        if res != INF_l:
                            ndp[idx] = res
                            if first_idx == n_l:
                                first_idx = idx

                    # Make current previous-layer state available for later points.
                    val = dp[idx]
                    if val != INF_l:
                        act = val + d
                        if act <= u:
                            ui = u
                            if ch_l[idx] == 0:
                                if ui < min0:
                                    min0 = ui
                                for pos in upaths_idx_l[idx]:
                                    if ui < tree0[pos]:
                                        tree0[pos] = ui
                                    else:
                                        break
                            else:
                                if ui < min1:
                                    min1 = ui
                                for pos in upaths_idx_l[idx]:
                                    if ui < tree1[pos]:
                                        tree1[pos] = ui
                                    else:
                                        break
                        else:
                            if ch_l[idx] == 0:
                                push(heap0, (act, idx))
                            else:
                                push(heap1, (act, idx))

                if first_idx == n_l:
                    return False

                dp = ndp
                start_idx = first_idx
                first_u = us_l[first_idx]
                limit = first_u + d

            return True

        lo = 0
        hi = two_side + 1
        while lo + 1 < hi:
            mid = (lo + hi) >> 1
            if feasible(mid):
                lo = mid
            else:
                hi = mid

        return lo

import sys

def solve():
    input = sys.stdin.buffer.readline
    line = input()
    if not line:
        return
    n = int(line)

    g = [[] for _ in range(n)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        g[a].append(b)
        g[b].append(a)

    parent = [-1] * n
    parent[0] = -2
    order = [0]
    stack = [0]

    while stack:
        u = stack.pop()
        for v in g[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            stack.append(v)
            order.append(v)

    dp = [1] * n
    ans = -1

    for u in reversed(order):
        t1 = t2 = t3 = t4 = 0
        cnt = 0

        for v in g[u]:
            if v == parent[u]:
                continue
            cnt += 1
            x = dp[v]

            if x > t1:
                t4 = t3
                t3 = t2
                t2 = t1
                t1 = x
            elif x > t2:
                t4 = t3
                t3 = t2
                t2 = x
            elif x > t3:
                t4 = t3
                t3 = x
            elif x > t4:
                t4 = x

        if cnt >= 3:
            dp[u] = 1 + t1 + t2 + t3

        if cnt >= 4:
            cand = 1 + t1 + t2 + t3 + t4
            if cand > ans:
                ans = cand

        if t1 > 1:
            cand = 1 + t1
            if cand > ans:
                ans = cand

    print(ans)

